const compactShotStyle=document.createElement('style');compactShotStyle.textContent='.shot-script-editor .shot-list [data-main-shot]{display:block!important;white-space:nowrap!important;overflow:hidden;text-overflow:ellipsis;padding:10px 12px;min-height:42px;margin-bottom:6px;font-size:13px}.shot-script-editor .shot-list [data-main-shot] b{display:inline;white-space:nowrap;font-size:inherit}.shot-timeline [data-child-card]:focus-visible{outline:2px solid var(--green);outline-offset:2px}.shot-timeline [data-child-card]:hover{border-color:#86b8a6}';document.head.append(compactShotStyle);
let selectedSubShot=0;
const shotsBeforeHierarchy=shots;
shots=function(){if(!data.shotScript?.hierarchical){shotsBeforeHierarchy();return}shotMode='shots';if(si>=data.shots.length)si=0;const main=data.shots[si];const check=ShotSchema.reconcile(data),subCount=data.shots.reduce((n,s)=>n+s.sub_shots.length,0);if(!main)return;if(selectedSubShot>=main.sub_shots.length)selectedSubShot=0;const sub=main.sub_shots[selectedSubShot];
document.querySelector('#panel').innerHTML=`<div class="section-head"><div><h3>主分镜与子分镜</h3><p>${data.shots.length} 个主分镜 · ${subCount} 个子分镜 · ${Number(Number(check.duration).toFixed(1))} 秒 / 目标 ${data.shotScript.target_duration_seconds} 秒</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button id="hierarchyImport">↓ 导入分镜 JSON</button><button id="hierarchyExport">导出分镜 JSON</button><button id="hierarchyArchives">旧版分镜与视频记录</button></div></div>${check.warnings.length?'<p class="notice">'+esc(check.warnings.join('；'))+'</p>':''}<div class="editor shot-script-editor"><div class="card shot-list"><div class="mini-label">分镜列表</div>${data.shots.map((m,i)=>`<button data-main-shot="${i}" title="${esc(m.shot_id+' · '+m.title)}" class="${i===si?'primary':''}"><b>${esc(m.shot_id)} · ${esc(m.title)}</b></button>`).join('')}</div><div class="card"><div class="preview-head"><b>${esc(main.shot_id)} · ${esc(main.title)}</b><span class="subtle">${Number(Number(main.duration).toFixed(1))} 秒</span></div><p class="subtle">${esc(main.scene_name)} · 全片 ${Number(Number(main.start_time).toFixed(1))}–${Number(Number(main.end_time).toFixed(1))} 秒</p><p>一次生成完整主分镜；下方子分镜使用片段内的相对时间。</p><div class="shot-timeline">${main.sub_shots.map((c,i)=>`<div class="card" data-child-card="${i}" role="button" tabindex="0" aria-pressed="${i===selectedSubShot}" aria-label="选择子分镜 ${esc(c.sub_shot_id)}" style="cursor:pointer;${i===selectedSubShot?'border-color:var(--green)':''}"><b>${Number(Number(c.start_offset_seconds).toFixed(1))}–${Number(Number(c.end_offset_seconds).toFixed(1))} 秒 · ${esc(c.sub_shot_id)}</b><p>${esc(c.visual_action)}</p>${c.dialogue?'<p class="subtle">'+esc(characterSpeaker(c.dialogue.speaker_id))+(c.dialogue.offscreen?'（画外声音，不出镜）':'')+'：'+esc(c.dialogue.text)+'</p>':'<p class="subtle">无对白</p>'}</div>`).join('')}</div><div class="divider"></div><b>本主分镜固定 Picture 顺序</b><p class="subtle">所有子分镜共用这组参考图。图片路径是预留字段，实际使用下面显示的本机版本。</p>${referenceCards(main)}<button id="hierarchyBindings">导出本主分镜参考图绑定</button></div><div class="card"><div class="right-title">主分镜设定</div>${field('主分镜标题','mainTitle',main.title)}<p class="subtle">总时长 ${Number(Number(main.duration).toFixed(1))} 秒，由子分镜时长自动合计 · 上限 ${data.shotScript.max_main_shot_duration_seconds||15} 秒</p><div class="divider"></div><div class="right-title">子分镜 ${esc(sub.sub_shot_id)}</div>${field('画面、动作与运镜','childAction',sub.visual_action,4)}${field('子分镜时长（秒）','childDuration',sub.duration_seconds)}<label>说话角色<select id="childSpeaker"><option value="">无对白</option>${data.characters.map(c=>`<option value="${esc(c.id||c.character_id)}">${esc(c.name)}</option>`).join('')}</select></label>${field('对白内容','childDialogue',sub.dialogue?.text||'',3)}<label style="display:flex;align-items:center;gap:8px"><input id="childOffscreen" type="checkbox" style="width:auto" ${sub.dialogue?.offscreen?'checked':''}>画外声音（不让该角色出镜）</label><button id="applyChildShot" class="wide">保存子分镜并更新时间轴</button><p id="childSaveStatus" class="subtle" role="status">动作和对白编辑后自动保存；时长变更时自动顺延后续子分镜。</p><div class="divider"></div>${field('主分镜首帧提示词','hierarchyImagePrompt',main.prompt,5)}${field('完整主分镜视频提示词','hierarchyVideoPrompt',main.video_generation.prompt,12)}<button id="rebuildHierarchyPrompt">更新动作对白并核对视频方案</button><p class="subtle">子分镜修改会保留已有 H3 结构，并要求逐项核对视频方案；旧版普通提示词按时间轴重建。多镜头精确切换仍需检查生成结果。</p></div></div>`;
document.querySelector('#hierarchyImport').onclick=()=>shotImportDialog.showModal();document.querySelector('#hierarchyExport').onclick=exportShotScript;document.querySelector('#hierarchyArchives').onclick=openShotArchives;document.querySelectorAll('[data-main-shot]').forEach(b=>b.onclick=()=>{si=Number(b.dataset.mainShot);selectedSubShot=0;save();render()});document.querySelectorAll('[data-child-card]').forEach(card=>{const activate=()=>{const index=Number(card.dataset.childCard);if(index===selectedSubShot)return;selectedSubShot=index;render();document.querySelector('[data-child-card=\"'+index+'\"]')?.focus({preventScroll:true});};card.onclick=activate;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}};});document.querySelectorAll('[data-shot-ref]').forEach(select=>select.onchange=()=>{main.pictureSelections??={};const binding=ShotSchema.bindings(main)[Number(select.dataset.shotRef)];main.pictureSelections[binding.picture]=select.value||undefined;save();render()});document.querySelector('#hierarchyBindings').onclick=()=>downloadShotBindings(main);document.querySelector('#mainTitle').oninput=e=>{main.title=e.target.value;save()};document.querySelector('#childSpeaker').value=sub.dialogue?.speaker_id||'';
function saveChild(refresh=false){const value=Number(document.querySelector('#childDuration').value);const sum=main.sub_shots.reduce((n,s)=>n+(s===sub?value:s.duration_seconds),0);if(!Number.isFinite(value)||value<=0||sum>(data.shotScript.max_main_shot_duration_seconds||15)){document.querySelector('#childSaveStatus').textContent='时长需大于0，且主分镜总长不能超过上限；未覆盖上次有效内容。';return}sub.visual_action=document.querySelector('#childAction').value;sub.duration_seconds=value;const speaker=document.querySelector('#childSpeaker').value;sub.dialogue=speaker?{...(sub.dialogue||{}),speaker_id:speaker,text:document.querySelector('#childDialogue').value,offscreen:document.querySelector('#childOffscreen').checked}:null;ShotSchema.reconcile(data);ShotSchema.rebuildMainPrompt(main,data);save();document.querySelector('#hierarchyVideoPrompt').value=main.video_generation.prompt;document.querySelector('#childSaveStatus').textContent='动作与对白已保存；请在视频生成页核对各视频方案后再提交';if(typeof updateShotReadiness==='function')updateShotReadiness(main);if(refresh)render();}
document.querySelector('#childAction').oninput=()=>saveChild();document.querySelector('#childDialogue').oninput=()=>saveChild();document.querySelector('#childSpeaker').onchange=()=>saveChild();document.querySelector('#childOffscreen').onchange=()=>saveChild();const duration=document.querySelector('#childDuration');duration.type='number';duration.min='0.1';duration.step='0.1';duration.onchange=()=>saveChild(true);document.querySelector('#applyChildShot').onclick=()=>saveChild(true);document.querySelector('#hierarchyImagePrompt').oninput=e=>{main.prompt=e.target.value;main.generation.image_prompt=e.target.value;save()};document.querySelector('#hierarchyVideoPrompt').oninput=e=>{main.video_generation.prompt=main.generation.video_prompt=e.target.value;save()};document.querySelector('#rebuildHierarchyPrompt').onclick=()=>{ShotSchema.rebuildMainPrompt(main,data);save();render()};
};
function characterSpeaker(id){return data.characters.find(c=>(c.id||c.character_id)===id)?.name||id;}
const hierarchyImportBefore=importProject;importProject=function(raw){if(ShotSchema.isHierarchical(raw)){importShotScript(raw);document.querySelector('#importDialog').close();return}hierarchyImportBefore(raw)};
const shotArchiveDialog=document.createElement('dialog');shotArchiveDialog.style.width='850px';document.body.append(shotArchiveDialog);
function openShotArchives(){shotArchiveDialog.replaceChildren();const heading=document.createElement('div');heading.className='modal-head';const title=document.createElement('h2');title.textContent='旧版分镜与视频记录';const close=document.createElement('button');close.textContent='✕';close.onclick=()=>shotArchiveDialog.close();heading.append(title,close);shotArchiveDialog.append(heading);const archives=data.shotScriptArchives||[];if(!archives.length){const p=document.createElement('p');p.textContent='暂无旧版记录。';shotArchiveDialog.append(p);}for(const archive of [...archives].reverse()){const block=document.createElement('details');const summary=document.createElement('summary');summary.textContent='V'+archive.version+' · '+archive.shots.length+' 镜头 · '+new Date(archive.saved_at).toLocaleString('zh-CN');block.append(summary);for(const target of [...archive.shots,...(archive.shotScript?.generation_clips||[])]){const versions=target.videoVersions||[];if(!versions.length)continue;const row=document.createElement('div');row.className='card';const label=document.createElement('p');label.textContent=(target.shot_id||target.clip_id)+' · '+(target.title||target.description||'');row.append(label);for(const [i,v]of versions.entries()){const a=document.createElement('a');a.href=v.video_url;a.target='_blank';a.rel='noopener';a.textContent='查看旧版视频 V'+(i+1)+' ↗';a.style.cssText='display:block;color:var(--green);margin:10px 0';row.append(a);}block.append(row);}const download=document.createElement('button');download.textContent='导出这个旧版本';download.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({...archive.shotScript,shots:archive.shots},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='shots-v'+archive.version+'-archive.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};block.append(download);shotArchiveDialog.append(block);}shotArchiveDialog.showModal();}
render();
